from concurrent.futures import ThreadPoolExecutor

# Simplified pseudo-Raft AppendEntries pattern
class Peer:
    def append_entries(self, term, prev_index, prev_term, entries):
        # check log consistency
        if not self.check_prev(prev_index, prev_term):
            return False
        self.log.extend(entries)
        return True

class Leader:
    def replicate(self, entry):
        self.log.append(entry)
        with ThreadPoolExecutor() as ex:
            futures = [ex.submit(p.append_entries, self.term, len(self.log)-2, self.log[-2]['term'] if len(self.log)>1 else 0, [entry]) for p in peers]
            successes = sum(1 for f in futures if f.result())
        if successes + 1 >= majority:
            self.commit_index += 1
            return True
        return False
